update public.data_connections set active = false where slug in ('qlik-rental-inventory','qlik-rental-receipts'); grant insert, delete on public.rentals to authenticated; grant update (name, property_type, rentable) on public.rentals to authenticated; create policy rentals_insert on public.rentals for insert to authenticated with check ((select public.has_department_access('alugueis'))); create policy rentals_delete on public.rentals for delete to authenticated using ((select public.has_department_access('alugueis')));